contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address makerOther, bool isCall, bool isLong, address baseAsset, uint256 strike, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce) public {
        require(makerOther != address(this));
        C.Order memory order;
        order.maker = address(this);
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        bytes32 h = c.hashOrder(order);
        require(!c.cancelledOrders(h));
        c.cancel(order);
        bool cancelledNow = c.cancelledOrders(h);
        // cancelling again (same caller = maker) is fine and keeps it cancelled
        c.cancel(order);
        bool stillCancelled = c.cancelledOrders(h);
        // someone else cannot cancel it (reverts), and it stays cancelled
        C.Order memory order2 = order;
        order2.maker = makerOther;
        bytes32 h2 = c.hashOrder(order2);
        require(!c.cancelledOrders(h2));
        bool reverted;
        c.cancel(order2);
        bool otherCancelled = c.cancelledOrders(h2);
        assert(cancelledNow && stillCancelled && !otherCancelled && reverted == false && !c.cancelledOrders(h) == false);
    }
    receive() external payable {}
}

