        for (uint256 i = 0; i < erc20Assets.length; i++)
            ea[i] = C.ERC20Asset(erc20Assets[i].token, erc20Assets[i].tokenAmount);
        C.ERC721Asset[] memory na = new C.ERC721Asset[](erc721Assets.length);
        for (uint256 i = 0; i < erc721Assets.length; i++)
            na[i] = C.ERC721Asset(erc721Assets[i].token, erc721Assets[i].tokenId);

