            floorTokens: ft,
            erc20Assets: ea,
            erc721Assets: na
        });

        bytes32 orderHash = c.hashOrder(order);

        // Before cancel the order must not be marked cancelled.
        require(!c.cancelledOrders(orderHash), "precondition: not yet cancelled");

        // Deciding call: the maker cancels its own order.
