contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens
    ) public {
        // Build an order made by this test contract (msg.sender of all calls on c).
        C.Order memory order;
        order.maker = address(this);
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;

        bytes32 orderHash = c.hashOrder(order);

        // Before cancelling, the order must not be cancelled.
        require(!c.cancelledOrders(orderHash), "pre: already cancelled");

        // Cancelling someone else's order must revert.
        C.Order memory other = order;
        other.maker = address(0x1234);
        bool cancelOtherReverted;
        bytes32 otherHash = c.hashOrder(other);
        // top-level call in try is not allowed; use try around the call as its own statement
        try this.cancelOther(other) { cancelOtherReverted = false; } catch { cancelOtherReverted = true; }

        // Cancel our own order.
        c.cancel(order);

        bool oursCancelled = c.cancelledOrders(orderHash);
        bool othersCancelled = c.cancelledOrders(otherHash);

        assert(
            cancelOtherReverted
            && !othersCancelled
            && oursCancelled
        );
    }

    function cancelOther(C.Order memory order) public {
        c.cancel(order);
    }
}

