contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens,
        C.ERC20Asset[] calldata erc20Assets,
        C.ERC721Asset[] calldata erc721Assets,
        bool wrongCaller
    ) public {
        C.Order memory order;
        order.maker = maker;
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;
        order.erc20Assets = erc20Assets;
        order.erc721Assets = erc721Assets;

        bytes32 orderHash = c.hashOrder(order);

        bool reverted;
        if (wrongCaller) {
            // we are never the maker, so cancel must revert
            try c.cancel(order) { reverted = false; } catch { reverted = true; }
        } else {
            // temporarily set maker to this contract so msg.sender == order.maker
            C.Order memory ownOrder = order;
            ownOrder.maker = address(this);
            bytes32 ownHash = c.hashOrder(ownOrder);
            c.cancel(ownOrder);
            reverted = false;
            assert(c.cancelledOrders(ownHash));
        }

        if (wrongCaller) {
            assert(reverted && !c.cancelledOrders(orderHash));
        } else {
            assert(reverted == false);
        }
    }

    receive() external payable {}
}

