contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        // order made by this test contract (msg.sender for all calls on c)
        C.Order memory own = C.Order(
            address(this), isCall, isLong, baseAsset, strike, premium,
            duration, expiration, nonce, whitelist, floorTokens, erc20Assets, erc721Assets
        );
        bytes32 ownHash = c.hashOrder(own);

        // the same order with a different maker must hash differently
        C.Order memory other = C.Order(
            address(0xBEEF), isCall, isLong, baseAsset, strike, premium,
            duration, expiration, nonce, whitelist, floorTokens, erc20Assets, erc721Assets
        );
        bytes32 otherHash = c.hashOrder(other);

        // cancelling our own order succeeds and marks exactly its hash
        c.cancel(own);
        bool ownCancelled = c.cancelledOrders(ownHash);
        bool otherCancelled = c.cancelledOrders(otherHash);

        // cancelling someone else's order reverts
        bool reverted;
        try c.cancel(other) { reverted = false; } catch { reverted = true; }

        assert(
            ownCancelled && !otherCancelled && reverted && ownHash != otherHash
        );
    }
    receive() external payable {}
}

