contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] memory whitelist, address target, address decoy) public payable {
        require(whitelist.length <= 4, "small list");

        bool result = c.isWhitelisted(whitelist, target);

        // compute expected answer independently
        bool expected = false;
        for (uint256 i = 0; i < whitelist.length; i++) {
            if (whitelist[i] == target) {
                expected = true;
            }
        }

        // cross-checks with distinct addresses: a non-member must not be whitelisted
        bool memberSelf = c.isWhitelisted(whitelist, decoy);
        bool decoyInList = false;
        for (uint256 j = 0; j < whitelist.length; j++) {
            if (whitelist[j] == decoy) {
                decoyInList = true;
            }
        }

        // empty whitelist never whitelists anyone (when target list nonempty is not required)
        address[] memory empty = new address[](0);
        bool emptyRes = c.isWhitelisted(empty, target);

        assert(result == expected && memberSelf == decoyInList && emptyRes == false);
    }

    receive() external payable {}
}
